import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as e,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"GitHub Copilot 上手","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/copilot/copilot.md","filePath":"zh/products/ai-coding/copilot/copilot.md","lastUpdated":1787048027000}'),i={name:"zh/products/ai-coding/copilot/copilot.md"};function l(r,t,d,h,n,p){return e(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="github-copilot-上手" tabindex="-1">GitHub Copilot 上手 <a class="header-anchor" href="#github-copilot-上手" aria-label="Permalink to &quot;GitHub Copilot 上手&quot;">​</a></h1><blockquote><p>这是一份<strong>教程型</strong>文档——按顺序读完，你会从&quot;装上 Copilot&quot;到&quot;知道四种界面各干什么、怎么把项目规范喂给它&quot;。</p><p>遇到不认识的名词看 <a href="./copilot-glossary.html">术语表</a>；要查快捷键和参数看 <a href="./copilot-cheatsheet.html">Cheatsheet</a>；要按场景抄现成做法看 <a href="./copilot-cookbook.html">Cookbook</a>。</p></blockquote><p>本指南目标：把 Copilot 从&quot;帮我补代码&quot;用成&quot;帮我干活&quot;。</p><h2 id="第-0-步-选订阅" tabindex="-1">第 0 步：选订阅 <a class="header-anchor" href="#第-0-步-选订阅" aria-label="Permalink to &quot;第 0 步：选订阅&quot;">​</a></h2><p>Copilot 有免费档，先用起来再说：</p><ul><li><strong>Copilot Free</strong> 免费，每月 2000 次代码补全，模型只能用自动选择。</li><li><strong>学生、教师、开源维护者</strong>通过资格验证后免费。</li><li>觉得额度不够再升级，各计划价格与限制见 <a href="./copilot-cheatsheet.html#计划对照">Cheatsheet · 计划对照</a>。</li></ul><p>一个前置事实：Copilot <strong>在 GitHub Enterprise Server 上不可用</strong>。公司用的是自建 GHES 的话，先确认这一点。</p><h2 id="第-1-步-装上并登录" tabindex="-1">第 1 步：装上并登录 <a class="header-anchor" href="#第-1-步-装上并登录" aria-label="Permalink to &quot;第 1 步：装上并登录&quot;">​</a></h2><p>以 VS Code 为例：装 GitHub Copilot 扩展 → 用 GitHub 账号登录 → 状态栏出现 Copilot 图标即可用。</p><p>在终端里用的话另装 CLI（<strong>注意有两套 CLI，别装错</strong>，区别见<a href="./copilot-glossary.html#copilot-cli">术语表</a>）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 独立 Copilot CLI（完整 agent，需要 Node.js 22+）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @github/copilot</span></span></code></pre></div><p>其他安装方式见 <a href="./copilot-cheatsheet.html#安装">Cheatsheet · Copilot CLI · 安装</a>。</p><h2 id="第-2-步-搞清它是怎么-懂你项目-的" tabindex="-1">第 2 步：搞清它是怎么&quot;懂你项目&quot;的 <a class="header-anchor" href="#第-2-步-搞清它是怎么-懂你项目-的" aria-label="Permalink to &quot;第 2 步：搞清它是怎么&quot;懂你项目&quot;的&quot;">​</a></h2><p>先纠正一个最常见的误解：<strong>Copilot 不是&quot;ChatGPT + 你的仓库&quot;</strong>。</p><p>它不绑定单一模型（不同订阅可用的模型集合不同），也没有把你的仓库喂进模型训练。它靠的是<strong>检索式上下文注入</strong>——编辑器把当前文件、你打开的标签页、你显式引用的文件、工具检索到的结果，拼进每一次请求。</p><p>这个机制决定了你的所有优化动作：</p><table tabindex="0"><thead><tr><th>你做什么</th><th>为什么有用</th></tr></thead><tbody><tr><td>打开相关文件再提问</td><td>打开的标签页会进上下文</td></tr><tr><td>用 <code>#file:</code> 显式引用</td><td>比让它自己找可靠</td></tr><tr><td>写自定义指令</td><td>每次请求自动带上，一次投入长期受益</td></tr></tbody></table><p>反过来，&quot;我们仓库很大所以 Copilot 肯定懂&quot;是错的。详细解释见<a href="./copilot-glossary.html#github-copilot">术语表 · GitHub Copilot</a>。</p><h2 id="第-3-步-四种界面-各管一段" tabindex="-1">第 3 步：四种界面，各管一段 <a class="header-anchor" href="#第-3-步-四种界面-各管一段" aria-label="Permalink to &quot;第 3 步：四种界面，各管一段&quot;">​</a></h2><p>Copilot 不是一个界面，是四类入口。<strong>选错入口是新手最大的效率损失。</strong></p><table tabindex="0"><thead><tr><th>界面</th><th>在哪</th><th>你怎么用</th><th>典型任务</th></tr></thead><tbody><tr><td><strong>代码补全</strong></td><td>编辑器里你打字的位置</td><td>打字 → 出灰字 → <code>Tab</code></td><td>补下一行、补样板代码</td></tr><tr><td><strong>Chat</strong></td><td>侧边栏 / 行内 / 终端</td><td>对话</td><td>解释、重构、多文件改动</td></tr><tr><td><strong>CLI</strong></td><td>终端</td><td>交互式 agent 会话</td><td>命令行任务、脚本</td></tr><tr><td><strong>Cloud agent</strong></td><td>GitHub 网页端 / Issue</td><td>派任务，后台跑，产出 PR</td><td>边界清楚的耗时任务</td></tr></tbody></table><h3 id="_3-1-代码补全" tabindex="-1">3.1 代码补全 <a class="header-anchor" href="#_3-1-代码补全" aria-label="Permalink to &quot;3.1 代码补全&quot;">​</a></h3><p>最简单也最容易到天花板：打字，出灰字，<code>Tab</code> 接受，<code>Escape</code> 忽略。</p><p>想让补全更准，就把意图写进注释：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 从 users 中过滤出 30 天内活跃且已验证邮箱的用户，</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 返回按 lastActiveAt 降序排序的数组</span></span></code></pre></div><p>比写&quot;处理用户&quot;有用得多——原因和写法见 <a href="./copilot-cookbook.html#在编辑器里写代码补全--行内-chat">Cookbook · 在编辑器里写代码</a>。</p><h3 id="_3-2-chat-先学会选模式" tabindex="-1">3.2 Chat：先学会选模式 <a class="header-anchor" href="#_3-2-chat-先学会选模式" aria-label="Permalink to &quot;3.2 Chat：先学会选模式&quot;">​</a></h3><p><code>⌃⌘I</code> 打开 Chat 视图，<code>⌘I</code> 在编辑器或终端里打开行内 Chat。</p><p>Chat 有三档自主程度，<strong>这是整份文档里最需要形成肌肉记忆的选择</strong>：</p><table tabindex="0"><thead><tr><th>模式</th><th>它能干什么</th><th>选它的信号</th></tr></thead><tbody><tr><td><strong>Ask</strong></td><td>只回答，不动代码</td><td>我要先搞懂</td></tr><tr><td><strong>Edit</strong></td><td>改你指定的文件，你逐条看 diff</td><td>我知道改哪，不想手写</td></tr><tr><td><strong>Agent</strong></td><td>自己决定改哪些文件、跑命令、多轮迭代</td><td>我知道目标，不想管过程</td></tr></tbody></table><p>判断口诀：<strong>你能不能一眼看出它做错了。</strong> 能 → 往 Agent 走；不能 → 退回 Edit 甚至 Ask。</p><p>深入解释见<a href="./copilot-glossary.html#ask--edit--agent-三种模式">术语表 · Ask / Edit / Agent</a>，标准流程见 <a href="./copilot-cookbook.html#让-chat-干多文件改动">Cookbook · 让 Chat 干多文件改动</a>。</p><h3 id="_3-3-给-chat-加上下文-和" tabindex="-1">3.3 给 Chat 加上下文：<code>@</code> 和 <code>#</code> <a class="header-anchor" href="#_3-3-给-chat-加上下文-和" aria-label="Permalink to &quot;3.3 给 Chat 加上下文：\`@\` 和 \`#\`&quot;">​</a></h3><p>两个前缀，作用不同：</p><ul><li><strong><code>@</code> 是参与者</strong>——把提问限定到某个领域并注入该领域上下文。当前只有 <code>@github</code>、<code>@terminal</code>、<code>@vscode</code> 三个（加扩展贡献的）。</li><li><strong><code>#</code> 是工具与文件引用</strong>——<code>#file:路径</code> 引用文件，<code>#search</code>、<code>#read</code>、<code>#execute</code> 这类是工具集，MCP 服务器提供的工具也在这个列表里。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@terminal find the largest file in the src directory</span></span>
<span class="line"><span>#file:gameReducer.js #file:gameInit.js how are these files related</span></span></code></pre></div><blockquote><p>旧教程里常见的 <code>@workspace</code>、<code>#editor</code>、<code>#git</code>、<code>#vscodeAPI</code> <strong>已经不在官方清单里</strong>了——代码库检索下沉成了工具，Agent 模式会自主调用。完整的已退役清单见<a href="./copilot-glossary.html#已退役或已改名的概念">术语表</a>。</p></blockquote><p>完整的参与者、工具集、斜杠命令清单见 <a href="./copilot-cheatsheet.html#聊天参与者">Cheatsheet</a>。</p><h3 id="_3-4-终端-cli" tabindex="-1">3.4 终端：CLI <a class="header-anchor" href="#_3-4-终端-cli" aria-label="Permalink to &quot;3.4 终端：CLI&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">copilot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 启动交互式会话</span></span></code></pre></div><p>会话里 <code>@ 文件名</code> 引用文件、<code>! 命令</code> 跑 shell、<code>Shift+Tab</code> 在 standard / plan / autopilot 之间切。</p><p>它和 Chat 最本质的区别：<strong>它有副作用</strong>——会真的改文件、真的跑命令，所以有分级权限（默认询问 / 辅助 / 全部允许）。第一次用建议保持默认，逐条看它想跑什么。</p><h3 id="_3-5-云端-cloud-agent" tabindex="-1">3.5 云端：Cloud agent <a class="header-anchor" href="#_3-5-云端-cloud-agent" aria-label="Permalink to &quot;3.5 云端：Cloud agent&quot;">​</a></h3><p>在 GitHub Issue 或网页端派任务，它开分支、改代码、开 PR。适合&quot;边界清楚、耗时、不需要你随时介入&quot;的活。写任务描述的要点见 <a href="./copilot-cookbook.html#把任务扔到云端cloud-agent">Cookbook · 把任务扔到云端</a>。</p><blockquote><p>注意它曾叫 &quot;coding agent&quot;，官方已改称 cloud agent；另外 Chat 里的 <strong>Agent 模式</strong>跑在你本地，和 Cloud agent 不是一回事。</p></blockquote><p>另外两个官方入口，第一天不用练：<strong>github.com 上的 Copilot Chat</strong>（<code>https://github.com/copilot</code>）和 <strong>Copilot app</strong>（桌面，并行会话）。什么时候用见<a href="./">学习地图</a>。<strong>GitHub Spark</strong> 正在关停，不要新建应用，见 <a href="./copilot-cookbook.html">Cookbook · Spark</a>。</p><h2 id="第-4-步-把重复的要求沉淀下来" tabindex="-1">第 4 步：把重复的要求沉淀下来 <a class="header-anchor" href="#第-4-步-把重复的要求沉淀下来" aria-label="Permalink to &quot;第 4 步：把重复的要求沉淀下来&quot;">​</a></h2><p>到这一步你已经会用四种界面了。<strong>真正拉开差距的是这一步</strong>——不再每次重复描述项目约定，而是写进文件让 Copilot 自动带上。</p><p>三类机制，生命周期不同：</p><table tabindex="0"><thead><tr><th>机制</th><th>触发方式</th><th>解决什么</th></tr></thead><tbody><tr><td><strong>自定义指令</strong></td><td>自动，每次对话都带</td><td>恒定约束（「我们用 TypeScript strict」）</td></tr><tr><td><strong>提示文件</strong></td><td>手动，<code>/名字</code> 调用</td><td>可复用的完整任务（「按模板生成表单」）</td></tr><tr><td><strong>自定义 Agent</strong></td><td>切换到该 agent</td><td>角色切换（「你现在是代码审查员」）</td></tr></tbody></table><p><strong>从一个文件开始就够</strong>——在仓库根建 <code>.github/copilot-instructions.md</code>：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 项目约定</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TypeScript strict 模式，不允许 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`any\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 组件一律函数式 + hooks，不写 class 组件</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 测试用 Vitest</span></span></code></pre></div><p>判断标准：<strong>同一句话你在 prompt 里写过三次以上，就该写进自定义指令。</strong></p><p>写法要点和进阶（路径级指令、<code>AGENTS.md</code>、提示文件 frontmatter）见 <a href="./copilot-cookbook.html#沉淀项目规范自定义指令">Cookbook · 沉淀项目规范</a> 和 <a href="./copilot-cheatsheet.html#自定义指令">Cheatsheet · 自定义指令</a>。</p><h2 id="第-5-步-接外部工具-mcp" tabindex="-1">第 5 步：接外部工具（MCP） <a class="header-anchor" href="#第-5-步-接外部工具-mcp" aria-label="Permalink to &quot;第 5 步：接外部工具（MCP）&quot;">​</a></h2><p>需要 Copilot 访问数据库、内部 API、第三方服务时，接 MCP 服务器。接好后它提供的工具出现在 <code>#</code> 列表里，和内置工具一样用。</p><blockquote><p><strong>重要时效提醒</strong>：GitHub App 形态的 <strong>Copilot Extensions 已于 2025-11-10 日落</strong>，官方替代方案就是 MCP。旧教程里&quot;用 <code>@扩展名</code> 调用扩展&quot;已失效。VS Code 客户端侧的 Chat 扩展<strong>不受影响，仍然支持</strong>。详情见<a href="./copilot-glossary.html#mcpmodel-context-protocol">术语表 · MCP</a>。</p></blockquote><h2 id="第-6-步-养成安全习惯" tabindex="-1">第 6 步：养成安全习惯 <a class="header-anchor" href="#第-6-步-养成安全习惯" aria-label="Permalink to &quot;第 6 步：养成安全习惯&quot;">​</a></h2><ul><li><strong>永远审查生成的代码</strong>，尤其是权限判断、SQL 拼接、加密、支付相关。</li><li><strong>用自动化测试当护栏</strong>——先确认测试正确，再让它改实现。</li><li>需要确认某段建议是否与公开代码高度相似时，用<a href="https://docs.github.com/en/copilot/how-tos/get-code-suggestions/find-matching-code" target="_blank" rel="noreferrer">官方匹配日志</a>。</li><li>Agent 模式和 CLI 会执行命令，<strong>不确定的命令别按同意</strong>。</li></ul><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>觉得&quot;它老是不懂我&quot; → <a href="./copilot-cookbook.html#提示原则">Cookbook · 提示原则</a></li><li>想查某个快捷键 / 命令 / 配置键 → <a href="./copilot-cheatsheet.html">Cheatsheet</a></li><li>看到不认识的名词，或怀疑某个说法过时了 → <a href="./copilot-glossary.html">术语表</a>，尤其是<a href="./copilot-glossary.html#已退役或已改名的概念">已退役概念</a></li></ul><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://docs.github.com/en/copilot" target="_blank" rel="noreferrer">GitHub Copilot 官方文档</a></li><li><a href="https://code.visualstudio.com/docs/copilot/overview" target="_blank" rel="noreferrer">VS Code Copilot 文档</a></li><li><a href="https://code.visualstudio.com/docs/copilot/reference/copilot-vscode-features" target="_blank" rel="noreferrer">VS Code Copilot 功能参考</a></li><li><a href="https://www.youtube.com/playlist?list=PLj6YeMhvp2S5_hvBl2SE-7YCHYlLQ0bPt" target="_blank" rel="noreferrer">GitHub Copilot 系列视频</a></li></ul><p>更完整的、按可信度排序的信息源清单见 <a href="./copilot-cheatsheet.html#高质量信息源">Cheatsheet · 高质量信息源</a>。</p>`,64)])])}const C=o(i,[["render",l]]);export{b as __pageData,C as default};
